        #region BulkInsertMetodlar
        public async Task BulkInsertEtiketLogDataAsync(SqlConnection connection, IEnumerable<EtiketLog_Temp> data)
        {
            try
            {
                var dataTable = new DataTable();
                var accessor = TypeAccessor.Create(typeof(EtiketLog_Temp)); // FastMember ile erişim

                // DataTable'a sütunları ekleyelim
                var members = accessor.GetMembers();
                foreach (var member in members)
                {
                    dataTable.Columns.Add(member.Name);
                }

                // Verileri DataTable'a ekleyelim
                foreach (var item in data)
                {
                    var row = dataTable.NewRow();
                    foreach (var member in members)
                    {
                        row[member.Name] = accessor[item, member.Name];
                    }
                    dataTable.Rows.Add(row);
                }

                // Bağlantıyı açıyoruz
                if (connection.State != ConnectionState.Open)
                {
                    await connection.OpenAsync(); // Bağlantıyı açıyoruz
                }

                // SqlBulkCopy ile veriyi MSSQL'e ekleyelim
                using (var bulkCopy = new SqlBulkCopy(connection))
                {
                    bulkCopy.DestinationTableName = "EtiketLog_Temp"; // Verinin ekleneceği tablo adı
                    // Dinamik kolon eşleştirmesi
                    foreach (DataColumn column in dataTable.Columns)
                    {
                        bulkCopy.ColumnMappings.Add(column.ColumnName, column.ColumnName);
                    }
                    await bulkCopy.WriteToServerAsync(dataTable); // Veriyi yazma
                }
            }
            catch (Exception)
            {

            }
            finally
            {
                // Bağlantıyı manuel olarak kapatıyoruz
                if (connection.State != ConnectionState.Closed)
                {
                    await connection.CloseAsync();
                }
            }
        }
        public async Task UpsertEtiketLogYeniDataAsync(
            SqlConnection connection,
            IEnumerable<EtiketLog_TempYeni> data,
            CancellationToken cancellationToken)
        {
            ArgumentNullException.ThrowIfNull(connection);
            ArgumentNullException.ThrowIfNull(data);

            // Aynı lokasyon ve etiket bu çevrimde birden fazla üretildiyse
            // en güncel kayıt tek satır olarak işleme alınır.
            var items = data
                .GroupBy(x => new { x.LokasyonId, x.EtiketId })
                .Select(g => g
                    .OrderByDescending(x => x.KayitZamani)
                    .First())
                .ToList();

            if (items.Count == 0)
                return;

            var dataTable = new DataTable();
            dataTable.Columns.Add("LokasyonId", typeof(int));
            dataTable.Columns.Add("SuKaynakId", typeof(int));
            dataTable.Columns.Add("SayacId", typeof(int));
            dataTable.Columns.Add("EtiketId", typeof(int));
            dataTable.Columns.Add("KayitZamani", typeof(DateTime));
            dataTable.Columns.Add("Deger", typeof(decimal));

            foreach (var item in items)
            {
                var row = dataTable.NewRow();
                row["LokasyonId"] = item.LokasyonId;
                row["SuKaynakId"] = item.SuKaynakId;
                row["SayacId"] = item.SayacId;
                row["EtiketId"] = item.EtiketId;
                row["KayitZamani"] = item.KayitZamani;
                row["Deger"] = item.Deger.HasValue
                    ? item.Deger.Value
                    : DBNull.Value;

                dataTable.Rows.Add(row);
            }

            SqlTransaction? transaction = null;

            try
            {
                if (connection.State != ConnectionState.Open)
                    await connection.OpenAsync(cancellationToken);

                // Unique index kullanılmadığı için iki worker örneğinin aynı anda
                // aynı etiketi INSERT etmesini önlemek amacıyla SERIALIZABLE kullanılır.
                transaction = connection.BeginTransaction(IsolationLevel.Serializable);

                // Geçici tablonun tipleri hedef tablodan alınır. Böylece Deger alanının
                // precision/scale değeri dahil olmak üzere kolon tipleri birebir eşleşir.
                const string createStageTableSql = @"
                    SELECT TOP (0)
                        LokasyonId,
                        SuKaynakId,
                        SayacId,
                        EtiketId,
                        KayitZamani,
                        Deger
                    INTO #EtiketLogTempYeniStage
                    FROM dbo.EtiketLog_TempYeni;";

                using (var createCommand = new SqlCommand(
                           createStageTableSql,
                           connection,
                           transaction))
                {
                    createCommand.CommandTimeout = 30;
                    await createCommand.ExecuteNonQueryAsync(cancellationToken);
                }

                using (var bulkCopy = new SqlBulkCopy(
                           connection,
                           SqlBulkCopyOptions.TableLock,
                           transaction))
                {
                    bulkCopy.DestinationTableName = "#EtiketLogTempYeniStage";
                    bulkCopy.BatchSize = items.Count;
                    bulkCopy.BulkCopyTimeout = 30;
                    bulkCopy.EnableStreaming = true;

                    bulkCopy.ColumnMappings.Add("LokasyonId", "LokasyonId");
                    bulkCopy.ColumnMappings.Add("SuKaynakId", "SuKaynakId");
                    bulkCopy.ColumnMappings.Add("SayacId", "SayacId");
                    bulkCopy.ColumnMappings.Add("EtiketId", "EtiketId");
                    bulkCopy.ColumnMappings.Add("KayitZamani", "KayitZamani");
                    bulkCopy.ColumnMappings.Add("Deger", "Deger");

                    await bulkCopy.WriteToServerAsync(dataTable, cancellationToken);
                }

                const string upsertSql = @"
                    UPDATE hedef
                    SET
                        hedef.SuKaynakId = kaynak.SuKaynakId,
                        hedef.SayacId = kaynak.SayacId,
                        hedef.KayitZamani = kaynak.KayitZamani,
                        hedef.Deger = kaynak.Deger
                    FROM dbo.EtiketLog_TempYeni AS hedef WITH (UPDLOCK, HOLDLOCK)
                    INNER JOIN #EtiketLogTempYeniStage AS kaynak
                        ON kaynak.LokasyonId = hedef.LokasyonId
                       AND kaynak.EtiketId = hedef.EtiketId;

                    INSERT INTO dbo.EtiketLog_TempYeni
                    (
                        LokasyonId,
                        SuKaynakId,
                        SayacId,
                        EtiketId,
                        KayitZamani,
                        Deger
                    )
                    SELECT
                        kaynak.LokasyonId,
                        kaynak.SuKaynakId,
                        kaynak.SayacId,
                        kaynak.EtiketId,
                        kaynak.KayitZamani,
                        kaynak.Deger
                    FROM #EtiketLogTempYeniStage AS kaynak
                    WHERE NOT EXISTS
                    (
                        SELECT 1
                        FROM dbo.EtiketLog_TempYeni AS hedef WITH (UPDLOCK, HOLDLOCK)
                        WHERE hedef.LokasyonId = kaynak.LokasyonId
                          AND hedef.EtiketId = kaynak.EtiketId
                    );";

                using (var upsertCommand = new SqlCommand(
                           upsertSql,
                           connection,
                           transaction))
                {
                    upsertCommand.CommandTimeout = 60;
                    await upsertCommand.ExecuteNonQueryAsync(cancellationToken);
                }

                transaction.Commit();
            }
            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
            {
                transaction?.Rollback();
                throw;
            }
            catch (Exception ex)
            {
                transaction?.Rollback();
                _logger.LogError(
                    ex,
                    "EtiketLog_TempYeni toplu UPSERT işlemi sırasında hata oluştu.");
                throw;
            }
            finally
            {
                transaction?.Dispose();

                if (connection.State != ConnectionState.Closed)
                    await connection.CloseAsync();
            }
        }

