                        PlcLogYaz("OSB Yem su izleme için plc bağlantısı sağlandı");
                    }
                    if (plcRead == 0 && !activeAlarms.Any(x => x.LokasyonId == lokasyonId && x.AlarmEnum == (int)AlarmLogTipler.Plc_Okunmuyor))
