        private async Task<IEnumerable<EtiketLog_TempYeni>> GetEtiketLogYeniDataForBulkInsertViolAsync(CancellationToken stoppingToken)
        {
            var lokasyonId = 15;
            var now = DateTime.Now;
            List<EtiketLog_TempYeni> etiketLogs = new List<EtiketLog_TempYeni>();
            SuIzlemeNodeRed? model;
            using (var scope = _serviceProvider.CreateScope())
            {
                var suHatScadaDbContext = scope.ServiceProvider.GetRequiredService<SuHatScadaDbContext>();
                model = await suHatScadaDbContext.SuIzlemeNodeRed.AsNoTracking().Where(x => x.LokasyonId == lokasyonId && x.KayitZamani.Value.Date == now.Date).OrderByDescending(x => x.Id).FirstOrDefaultAsync(stoppingToken);
                if (model == null)
                {
                    var plcRead = 0;
                    var plcConnected = 1;
                    etiketLogs.Add(new EtiketLog_TempYeni { LokasyonId = 15, SuKaynakId = 0, SayacId = 0, EtiketId = 296, KayitZamani = DateTime.Now, Deger = (decimal?)plcRead });
                    etiketLogs.Add(new EtiketLog_TempYeni { LokasyonId = 15, SuKaynakId = 0, SayacId = 0, EtiketId = 297, KayitZamani = DateTime.Now, Deger = (decimal?)plcConnected });
                    var activeAlarms = await _alarmCacheService.GetAlarmLogsAsync(lokasyonId/*, DateTime.Now*/);
                    List<AlarmLog> alarmLogs = new List<AlarmLog>();
                    if (plcRead == 0 && !activeAlarms.Any(x => x.LokasyonId == lokasyonId && x.AlarmEnum == (int)AlarmLogTipler.Plc_Okunmuyor))
                    {
                        PlcLogYaz("Viol su izleme için plc okunmuyor");
                        //if (!activeAlarms.Any(x => x.LokasyonId == lokasyonId && x.AlarmEnum == (int)AlarmLogTipler.Plc_Okunmuyor))
                        {
                            alarmLogs.Add(new AlarmLog { KayitZamani = now, AlarmSeviye = AlarmSeviye.Kritik, LokasyonId = lokasyonId, AlarmId = 597, AlarmEnum = (int?)AlarmLogTipler.Plc_Okunmuyor, Mesaj = "Viol su izleme için " + AlarmLogTipler.Plc_Okunmuyor.GetDescription(), Aktif = true, Silindi = false });
                            _alarmCacheService.ClearMemoryCache(lokasyonId);
                        }
                    }
                    else if (plcRead == 1 && activeAlarms.Any(x => x.LokasyonId == lokasyonId && x.AlarmEnum == (int)AlarmLogTipler.Plc_Okunmuyor))
                    {
                        await _alarmCacheService.SetAlarmPassive(lokasyonId, (int)AlarmLogTipler.Plc_Okunmuyor, AlarmSeviye.Kritik/*, now*/);
                    }
                    await BulkInsertAlarmLogDataAsync(_sqlConnection, alarmLogs);
                    return etiketLogs;
                }
                if (model != null)
                {
                    var plcRead = model.Durum;
                    var plcConnected = model.Durum;
                    var activeAlarms = await _alarmCacheService.GetAlarmLogsAsync(lokasyonId/*, DateTime.Now*/);
                    List<AlarmLog> alarmLogs = new List<AlarmLog>();
                    if (plcConnected == 0 && !activeAlarms.Any(x => x.LokasyonId == lokasyonId && x.AlarmEnum == (int)AlarmLogTipler.Plc_Koptu))
                    {
