        private async Task<IEnumerable<AlarmLog>> GetUretilmisAlarmLogDataForSuHat(CancellationToken stoppingToken)
        {
            List<AlarmLog> alarmLogs = new List<AlarmLog>();
            var now = DateTime.Now;
            //rahmiye su deposundaki aktif alarmlar
            var rahmiyeLokasyonId = 13;
            var activeAlarmsRahmiye = await _alarmCacheService.GetAlarmLogsAsync(rahmiyeLokasyonId);
            if (activeAlarmsRahmiye.Any(x => x.LokasyonId == rahmiyeLokasyonId && x.AlarmEnum == (int)AlarmLogTipler.A4_SebekeElektrikYok))
            {
                if (activeAlarmsRahmiye.Any(x => x.LokasyonId == rahmiyeLokasyonId && x.AlarmEnum == (int)AlarmLogTipler.Plc_Koptu))
                {
                    if (!activeAlarmsRahmiye.Any(x => x.LokasyonId == rahmiyeLokasyonId && x.AlarmEnum == (int)AlarmLogTipler.A33_RahmiyeElektrikKesintisiDevamEdiyor))
                    {
                        alarmLogs.Add(new AlarmLog { KayitZamani = now, AlarmSeviye = AlarmSeviye.Normal, AlarmId = 885, AlarmEnum = (int?)AlarmLogTipler.A33_RahmiyeElektrikKesintisiDevamEdiyor, LokasyonId = rahmiyeLokasyonId, Mesaj = AlarmLogTipler.A33_RahmiyeElektrikKesintisiDevamEdiyor.GetDescription(), Aktif = true, Silindi = false });
                        _alarmCacheService.ClearMemoryCache(rahmiyeLokasyonId);
                    }
                }
                else
                {
                    if (activeAlarmsRahmiye.Any(x => x.LokasyonId == rahmiyeLokasyonId && x.AlarmEnum == (int)AlarmLogTipler.A33_RahmiyeElektrikKesintisiDevamEdiyor))
                    {
