                        _alarmCacheService.ClearMemoryCache(cayKarsisiLokasyonId);
                    }
                }
                else
                {
                    if (activeAlarmsCayKarsisi.Any(x => x.LokasyonId == cayKarsisiLokasyonId && x.AlarmEnum == (int)AlarmLogTipler.A33_CayKarsisiElektrikKesintisiDevamEdiyor))
