        private async Task<IEnumerable<AlarmLog>> GetAlarmLogDataForBulkInsertViol(CancellationToken stoppingToken)
        {
            var lokasyonId = 15;
            var now = DateTime.Now;
            List<AlarmLog> alarmLogs = new List<AlarmLog>();
            SuIzlemeNodeRed? model;
            using (var scope = _serviceProvider.CreateScope())
            {
                var suHatScadaDbContext = scope.ServiceProvider.GetRequiredService<SuHatScadaDbContext>();
                model = await suHatScadaDbContext.SuIzlemeNodeRed.AsNoTracking().Where(x => x.LokasyonId == lokasyonId && x.KayitZamani.Value.Date == now.Date).OrderByDescending(x => x.Id).FirstOrDefaultAsync(stoppingToken);
                if (model != null)
                {
                    if (model.Durum == 1)
                    {
                        if (model.Veriler != null)
                        {
                            ViolNodeRedModel violNodeRedModel = JsonSerializer.Deserialize<ViolNodeRedModel>(model.Veriler);

                            var activeAlarms = await _alarmCacheService.GetAlarmLogsAsync(lokasyonId/*, now*/);

                            //if (activeAlarms.Any(x => x.KayitZamani.Value.Date != now.Date) || activeAlarms.Count() == 0)
                            //{
                            //    await _alarmCacheService.SetOldAlarmsPassiveByLokasyonId(lokasyonId, now);
                            //    activeAlarms = await _alarmCacheService.GetActiveAlarmsByLokasyonId(lokasyonId, now);
                            //}

                            bool alarm1 = violNodeRedModel.Alarm_1.GetValueOrDefault(false);
                            if (!activeAlarms.Any(x => x.LokasyonId == lokasyonId && x.AlarmEnum == (int)AlarmLogTipler.A1_AlarmVar))
                            {
